// Internal: pad input with zeros
static void ConvLayer_add_pad(ConvLayer *layer, const float *pfInput) {
    int C = layer->nInputNum;
    int Wp = layer->nInputPadWidth;
    int W  = layer->nInputWidth;
    int P  = layer->nPad;
    for (int m = 0; m < C; ++m) {
        for (int i = 0; i < Wp; ++i) {
            for (int j = 0; j < Wp; ++j) {
                int idx = m * layer->nInputPadSize + i * Wp + j;
                if (i < P || i >= Wp - P || j < P || j >= Wp - P) {
                    layer->pfInputPad[idx] = 0.0f;
                } else {
                    int oi = i - P;
                    int oj = j - P;
                    layer->pfInputPad[idx] = pfInput[m * layer->nInputSize + oi * W + oj];
                }
            }
        }
    }
}

